export type ApiRoute = (typeof API_ROUTES)[number];
/** `GET /api/v1/students/{id}` -> `/api/v1/students/{id}` */
export type ApiPath<Method extends string = string> = ApiRoute extends infer R ? (R extends `${Method} ${infer P}` ? P : never) : never;
